using System;
using System.Collections;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ApianDroneOmenData", menuName = "Data/Battle/Omens System/Omen Data/Austra/ApianDroneOmenData")]
public class ApianDroneOmenData : OnStartOfBattleOmenData
{
	[Header("ApianDroneOmenData")]
	[SerializeField]
	private DodgeEffect dodgeEffect;

	[SerializeField]
	private int dodgeDecreaseAmount;

	[SerializeField]
	private OmenLogicActionFace playerTurnDodgeOmenLogicActionFace;

	[SerializeField]
	private OmenLogicActionFace enemiesTurnDodgeOmenLogicActionFace;

	[NonSerialized]
	private OmenInstance omenInstance;

	[NonSerialized]
	private int drawAmount;

	private Action<GameObject> dodgeOmenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		drawAmount = 0;
		dodgeOmenAction = delegate(GameObject unitThatDodged)
		{
			if (!ReferenceSingleton<AssetsReference>.Instance.CurrentCorruptedAnimals.IsAllEnemiesDefeated())
			{
				if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.PlayerTurn)
				{
					if (unitThatDodged.GetComponent<CompanionCorruptionStats>() != null)
					{
						if (drawAmount == 0)
						{
							ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ActivateOmenCoroutine());
							ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
						}
						drawAmount++;
						omenInstance.EnqueueOmenFeedbackAndPlay();
						unitThatDodged.GetComponent<UnitEffects>().IsEffectActiveAndDecreaseEffect(dodgeEffect, dodgeDecreaseAmount);
					}
				}
				else if (ReferenceSingleton<TurnManager>.Instance.CurrentTurn == ReferenceSingleton<TurnManager>.Instance.EnemyTurn && unitThatDodged.GetComponent<CompanionCorruptionStats>() != null)
				{
					omenInstance.EnqueueOmenFeedbackAndPlay();
					enemiesTurnDodgeOmenLogicActionFace.OmenLogic.ActivateOmen(enemiesTurnDodgeOmenLogicActionFace.ActionFace.BattleAction, enemiesTurnDodgeOmenLogicActionFace.ActionFace.ActionValue, null, null);
				}
			}
		};
		ReferenceSingleton<AustraOmensHandler>.Instance.OnDodgeOmenActions.Add(dodgeOmenAction);
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.OnDodgeOmenActions.Remove(dodgeOmenAction);
		base.OmenRemoved();
	}

	private IEnumerator ActivateOmenCoroutine()
	{
		omenInstance.EnqueueOmenFeedbackAndPlay();
		playerTurnDodgeOmenLogicActionFace.OmenLogic.ActivateOmen(playerTurnDodgeOmenLogicActionFace.ActionFace.BattleAction, drawAmount * playerTurnDodgeOmenLogicActionFace.ActionFace.ActionValue, null, null);
		drawAmount = 0;
		yield return InvokeAlternatives.WaitOneFrame();
	}

	public override string OmenConvertedDescription()
	{
		string arg = playerTurnDodgeOmenLogicActionFace.ActionFace.BattleAction.GetActionDescription(playerTurnDodgeOmenLogicActionFace.ActionFace.ActionValue).LowercaseFirst().RemoveLast();
		string localizedThenDecreaseThatSentinelEffect = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedThenDecreaseThatSentinelEffect(dodgeEffect, dodgeDecreaseAmount);
		string arg2 = enemiesTurnDodgeOmenLogicActionFace.ActionFace.BattleAction.GetActionDescription(enemiesTurnDodgeOmenLogicActionFace.ActionFace.ActionValue).LowercaseFirst().RemoveLastIfDotOrComma();
		return Smart.Format(GetOmenRawLocalizedDescription(), arg, localizedThenDecreaseThatSentinelEffect, arg2) + "\n" + base.OmenConvertedDescription();
	}
}
